import fs from 'node:fs';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const sourcePath = fileURLToPath(import.meta.url);
const source = fs.readFileSync(sourcePath, 'utf8');
const outputPath = sourcePath.replace(/\.mjs$/, '.json');
if (fs.existsSync(outputPath)) throw new Error('预检记录已存在');
const marker = 'A2_END_' + crypto.randomBytes(8).toString('hex');
const commands = String.raw`id
printf 'ROOT_PID_NAMESPACE\n'
readlink /proc/1/ns/pid
readlink /proc/self/ns/pid
printf 'BOOT_ID\n'
cat /proc/sys/kernel/random/boot_id
printf 'CHRONYD_IDENTITY\n'
cat /proc/308/stat
sed -n '/^Name:/p;/^State:/p;/^Pid:/p;/^PPid:/p;/^NSpid:/p' /proc/308/status
readlink /proc/308/exe
stat -Lc '%d %i %s %Y' /proc/308/exe
readlink /proc/308/ns/pid
readlink /proc/308/ns/mnt
tr '\000' '\n' < /proc/308/cmdline
printf 'ACTIVE_DEFAULT_CONFIG\n'
cat /proc/308/root/etc/chrony.conf
printf 'CHRONY_VERSION\n'
/proc/308/exe -v
printf 'CHRONY_TRACKING\n'
chronyc -n tracking
printf 'PARENT\n'
cat /proc/1/comm
readlink /proc/1/exe
printf 'CLOCKSOURCE\n'
cat /sys/devices/system/clocksource/clocksource0/current_clocksource
printf 'UBUNTU_ROOT_CANDIDATE\n'
for entry in /proc/[0-9]*/ns/pid; do
  ns=$(readlink "$entry") || continue
  if [ "$ns" = 'pid:[4026532235]' ]; then
    base=$(dirname "$(dirname "$entry")")
    if [ -x "$base/root/usr/bin/python3" ]; then
      printf '%s\n' "$base"
      cat "$base/comm"
      sed -n '/^NSpid:/p' "$base/status"
      cat "$base/root/etc/os-release"
      printf 'PYTHON_CHECK\n'
      chroot "$base/root" /usr/bin/python3 -c 'import os,sys,ctypes,time; print(sys.version); print(os.readlink("/proc/self/ns/pid") if os.path.exists("/proc/self/ns/pid") else "root PID outside mounted proc namespace"); print(os.pread(3,0,0) if False else os.listdir(3)[:3]); print(hasattr(os,"pidfd_open")); print(time.clock_gettime_ns(time.CLOCK_MONOTONIC_RAW))' 3</proc
      break
    fi
  fi
done
`;
const input = "stty -echo\n/bin/sh <<'A2_READONLY_SCRIPT'\n" + commands + "printf '\\n" + marker + "\\n'\nA2_READONLY_SCRIPT\nexit\n";
const child = spawn('C:\\Windows\\System32\\wsl.exe', ['--debug-shell'], {
  cwd: 'D:/ClaudeProjects/ai_acknowladge', windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'],
});
const started = new Date().toISOString();
const output = [];
const errors = [];
let matched = false;
let failure;
let closeTimer;
const deadline = setTimeout(() => { failure = '预检通道超过 20 秒'; child.kill(); }, 20000);
child.stdout.on('data', chunk => {
  output.push(chunk);
  const bytes = Buffer.concat(output);
  if (bytes.length > 1024 * 1024) { failure = '预检输出超限'; child.kill(); }
  const text = bytes.toString('utf8').replaceAll('\0', '').replace(/\u001b\[[0-9;?]*[A-Za-z]/g, '');
  if (!matched && text.split(/\r?\n/).some(line => line.replaceAll('\r', '').trim() === marker)) {
    matched = true;
    clearTimeout(deadline);
    closeTimer = setTimeout(() => child.kill(), 1000);
  }
});
child.stderr.on('data', chunk => errors.push(chunk));
child.stdin.on('error', error => { failure ??= error.message; });
const done = new Promise(resolve => {
  child.on('error', error => { failure = error.message; resolve({code:null,signal:null}); });
  child.on('close', (code, signal) => resolve({code,signal}));
});
child.stdin.end(Buffer.from(input, 'utf8'));
const result = await done;
clearTimeout(deadline);
clearTimeout(closeTimer);
const report = {
  recorded_at: started, finished_at: new Date().toISOString(), status: matched && !failure ? 'completed' : 'failed',
  scope: '已批准的管理员只读预检；未发送信号或写时钟参数。',
  source_file: sourcePath, source_sha256: crypto.createHash('sha256').update(source).digest('hex'), maintenance_source: source,
  command: ['wsl.exe','--debug-shell'], requested_stdin: input, ...result,
  marker_matched: matched, channel_disconnect: matched ? '完成标记后关闭本次 Windows 调试连接' : '超时或失败', error: failure,
  stdout: Buffer.concat(output).toString('utf8'), stderr: Buffer.concat(errors).toString('utf8'),
};
fs.writeFileSync(outputPath, JSON.stringify(report, null, 2) + '\n', { flag: 'wx' });
process.exitCode = report.status === 'completed' ? 0 : 1;
